open('submission.py','w').write('''"""3B current core temperature from causal history."""

def _first(hist, key, default):
    for row in hist:
        if row.get(key) is not None:
            return row[key]
    return default


def _elapsed_min(hist):
    t0 = hist[0]["time_min"]
    t1 = hist[-1]["time_min"]
    if t0 is None or t1 is None:
        return max(0.0, len(hist) - 1.0)
    return max(0.0, float(t1) - float(t0))


def _mean_and_slope(hist):
    watts = _first(hist, "watts", 160.0)
    mass = _first(hist, "mass", 70.0)
    age = _first(hist, "age", 30.0)
    if watts is None:
        watts = 160.0
    if mass is None or mass <= 1:
        mass = 70.0
    if age is None:
        age = 30.0
    wkg = float(watts) / float(mass)
    t = _elapsed_min(hist)
    # Fit on train.json: core ~ 1 + t + (W/kg)*t + W0 + age
    # T = 38.8694 - 0.0058285*W0 - 0.010742*age + (0.009288 + 0.006469*wkg)*t
    intercept = 38.8694148 - 0.005828496 * float(watts) - 0.010741654 * float(age)
    slope = 0.009288248 + 0.006468616 * wkg
    mean = intercept + slope * t
    # keep in a physiological band
    mean = min(40.8, max(36.2, mean))
    return mean, slope, t


def predict(request):
    hist = request["history"]
    if not hist:
        est = 37.4
        return {"mean": est, "lower": est - 0.7, "upper": est + 0.7}
    mean, slope, t = _mean_and_slope(hist)
    if request.get("task") == "3A":
        mean = mean + 15.0 * max(-0.02, min(0.05, slope))
        mean = min(41.0, max(36.2, mean))
    # slightly wider early (T0 uncertainty), tighter mid-session
    half = 0.55 + 0.25 * max(0.0, 1.0 - t / 20.0)
    half = min(2.4, max(0.25, half))
    return {"mean": float(mean), "lower": float(mean - half), "upper": float(mean + half)}
