import json, numpy as np
from scipy.optimize import minimize
train=json.load(open('train.json'))
ts=[]; ys=[]; pids=[]
for pid,data in train.items():
    t0=data[0]['time_min']
    for r in data:
        if r['core_temp'] is None: continue
        if pid=='H04' and r['time_min']>=52: continue
        ts.append(r['time_min']-t0); ys.append(r['core_temp']); pids.append(pid)
ts=np.array(ts,float); ys=np.array(ys,float)

def pred(theta, t):
    a,b,tau=theta
    tau=max(tau,5.0)
    return a + b*(1-np.exp(-t/tau))

def mae_all(theta):
    return np.mean(np.abs(pred(theta,ts)-ys))

def mae_person(theta):
    p=pred(theta,ts)
    by={}
    for pid,e in zip(pids, np.abs(p-ys)):
        by.setdefault(pid,[]).append(e)
    return np.mean([np.mean(v) for v in by.values()])

for x0 in [(37.25,1.85,31),(37.34,1.6,40),(37.3,2.0,35),(37.2,1.7,25)]:
    res=minimize(mae_person, x0, method='Nelder-Mead')
    print('x0', x0, 'theta', np.round(res.x,4), 'pmae', round(mae_person(res.x),4), 'all', round(mae_all(res.x),4))
