_A = 37.2764
_B = 1.5915
_TAU = 24.7365

# Empiric between-person SD of core at elapsed t (training).
_SD = [
    0.403, 0.398, 0.396, 0.385, 0.377, 0.364, 0.356, 0.347, 0.336, 0.330,
    0.319, 0.310, 0.301, 0.291, 0.289, 0.284, 0.285, 0.278, 0.281, 0.265,
