    0.233, 0.233, 0.236, 0.237, 0.237, 0.238, 0.241, 0.248, 0.257, 0.255,
    0.253, 0.257, 0.269, 0.290, 0.305, 0.307, 0.328, 0.339, 0.350, 0.324,
    0.330, 0.325, 0.335, 0.335, 0.335, 0.335, 0.300, 0.300, 0.300, 0.304,
]

def _elapsed_min(hist):
    times = [row.get("time_min") for row in hist if row.get("time_min") is not None]
    if len(times) >= 2:
        return max(0.0, float(times[-1]) - float(times[0]))
    if len(times) == 1:
        return max(0.0, float(len(hist) - 1))
    return max(0.0, float(len(hist) - 1))


def _curve(t):
    t = max(0.0, float(t))
    return _A + _B * (1.0 - math.exp(-t / _TAU))


def _sd(t):
    if t <= 0:
        return _SD[0]
    n = len(_SD)
    if t >= n - 1:
        return _SD[-1]
    i = int(t)
    f = t - i
    return _SD[i] * (1.0 - f) + _SD[i + 1] * f


def predict(request):
    hist = request.get("history") or []
    if not hist:
        est = _A
        half = 1.70 * _SD[0]
        return {"mean": est, "lower": est - half, "upper": est + half}
    t = _elapsed_min(hist)
    if request.get("task") == "3A":
        t = t + float(request.get("horizon_min") or 15)
    mean = min(40.6, max(36.3, _curve(t)))
    half = max(0.40, min(2.45, 1.70 * _sd(t)))
    return {"mean": float(mean), "lower": float(mean - half), "upper": float(mean + half)}
